528	// loadMultiRegistryTagsMetaCmd fetches tag metadata for one registry in the background.
529	// For Docker Hub it uses the Hub API; other registries return empty (no error).
530	func loadMultiRegistryTagsMetaCmd(registryURL, repo string) tea.Cmd {
531		return func() tea.Msg {
532			base := strings.ToLower(strings.TrimSuffix(registryURL, "/"))
533			isDockerhub := base == "docker.io" || base == "registry-1.docker.io"
534			if !isDockerhub {
535				return MultiRegistryTagsMetaMsg{RegistryURL: registryURL, Repo: repo, Meta: nil, Err: nil}
536			}
537			parts := strings.SplitN(repo, "/", 2)
538			if len(parts) != 2 {
539				return MultiRegistryTagsMetaMsg{RegistryURL: registryURL, Repo: repo, Meta: nil, Err: nil}
540			}
541			meta, err := fetchDockerHubTagsMeta(parts[0], parts[1])
542			return MultiRegistryTagsMetaMsg{RegistryURL: registryURL, Repo: repo, Meta: meta, Err: err}
543		}
544	}
