9	// dockerCmd describes one CLI invocation.
10	type dockerCmd struct {
11		// Args are passed to the binary verbatim, e.g. {"ps", "--format", "..."}.
12		Args []string
13		// Stdin is written to the process when non-empty. Used to keep secrets out
14		// of the process list (`docker login --password-stdin`).
15		Stdin string
16		// Combined merges stderr into the returned bytes. Docker writes failure
17		// detail to stderr, so mutating calls set this to produce a usable message;
18		// calls that parse stdout leave it false.
19		Combined bool
20		// Helper runs `docker-credential-<Helper>` instead of `docker`.
21		Helper string
22	}
23	
24	// dockerRunner is the seam every CLI invocation in this package passes through.
25	//
26	// The package talks to the Docker CLI rather than the SDK, which keeps the
27	// dependency light but makes the whole package untestable without a daemon.
28	// Routing through this interface lets tests exercise the argument building and
29	// output parsing — the parts that actually carry defects — against canned
30	// output.
31	type dockerRunner interface {
32		// LookPath reports whether the docker binary is reachable on PATH.
33		LookPath() error
34		// Run executes one invocation and returns its captured output.
35		Run(cmd dockerCmd) ([]byte, error)
36		// Build returns a ready-to-run command without executing it, for callers
37		// that hand the process to a terminal (tea.ExecProcess).
38		Build(args ...string) *exec.Cmd
39	}
40	
41	// cliRunner is the production dockerRunner: it shells out to the real binary.
42	type cliRunner struct{}
43	
44	func (cliRunner) LookPath() error {
45		_, err := exec.LookPath("docker")
46		return err
47	}
48	
49	func (cliRunner) Build(args ...string) *exec.Cmd {
50		return exec.Command("docker", args...)
51	}
52	
53	func (cliRunner) Run(dc dockerCmd) ([]byte, error) {
54		name := "docker"
55		if dc.Helper != "" {
56			name = "docker-credential-" + dc.Helper
57		}
58		cmd := exec.Command(name, dc.Args...) //nolint:gosec // helper name comes from ~/.docker/config.json
59		if dc.Stdin != "" {
60			cmd.Stdin = strings.NewReader(dc.Stdin)
61		}
62		if dc.Combined {
63			return cmd.CombinedOutput()
64		}
65		return cmd.Output()
66	}
67	
68	// runner is swapped by tests via stubRunner. Production code never reassigns
69	// it, so the package stays safe to call concurrently; tests that swap it must
70	// not run in parallel.
71	var runner dockerRunner = cliRunner{}
72	
73	// requireDocker reports the absence of the docker binary with the error message
74	// callers have always produced.
75	func requireDocker() error {
76		if err := runner.LookPath(); err != nil {
77			return fmt.Errorf("docker not found: %w", err)
78		}
79		return nil
80	}
81	
82	// dockerOutput runs `docker args...` and returns stdout only.
83	func dockerOutput(args ...string) ([]byte, error) {
84		return runner.Run(dockerCmd{Args: args})
85	}
86	
87	// dockerCombined runs `docker args...` and returns stdout and stderr merged.
88	func dockerCombined(args ...string) ([]byte, error) {
89		return runner.Run(dockerCmd{Args: args, Combined: true})
90	}
91	
92	// wrapErr reports a failed invocation whose stderr was not captured, keeping the
93	// underlying error for errors.Is/As.
94	func wrapErr(label string, err error) error {
95		return fmt.Errorf("%s failed: %w", label, err)
96	}
97	
98	// errWithOutput reports a failed invocation using the captured output, which
99	// carries Docker's own diagnostic.
100	func errWithOutput(label string, output []byte) error {
101		return fmt.Errorf("%s failed: %s", label, strings.TrimSpace(string(output)))
102	}
103	
104	// mutate runs a docker subcommand whose output only matters on failure, and
105	// wraps that output in an error prefixed with label (e.g. "docker stop failed").
106	func mutate(label string, args ...string) error {
107		output, err := dockerCombined(args...)
108		if err != nil {
109			return fmt.Errorf("%s failed: %s", label, strings.TrimSpace(string(output)))
110		}
111		return nil
112	}
113	
114	// prune runs a docker prune subcommand and returns its trimmed report.
115	func prune(label string, args ...string) (string, error) {
116		output, err := dockerCombined(args...)
117		if err != nil {
118			return "", fmt.Errorf("%s failed: %s", label, strings.TrimSpace(string(output)))
119		}
120		return strings.TrimSpace(string(output)), nil
121	}
122	
123	// splitLines splits trimmed command output into non-empty lines.
124	func splitLines(output []byte) []string {
125		trimmed := strings.TrimSpace(string(output))
126		if trimmed == "" {
127			return nil
128		}
129		var lines []string
130		for line := range strings.SplitSeq(trimmed, "\n") {
131			if line != "" {
132				lines = append(lines, line)
133			}
134		}
135		return lines
136	}
