17	// The package drives trivy and gitleaks as subprocesses, so the production
18	// runner cannot be exercised without both installed. Instead the test binary
19	// re-executes itself: TestMain notices the helper variables and behaves the way
20	// a scanner does — a report on stdout, progress on stderr, and an exit code that
21	// may mean "I found something" rather than "I failed".
22	const (
23		helperMode   = "DEVDESK_SCAN_HELPER"
24		helperStdout = "DEVDESK_SCAN_HELPER_STDOUT"
25		helperStderr = "DEVDESK_SCAN_HELPER_STDERR"
26		helperExit   = "DEVDESK_SCAN_HELPER_EXIT"
27		// helperFailOn names an argument the helper refuses. One binary is asked
28		// several different things — `docker images` and `docker run` both go to
29		// the same fake — so failing has to be selectable per subcommand.
30		helperFailOn = "DEVDESK_SCAN_HELPER_FAIL_ON"
31	)
32	
33	func TestMain(m *testing.M) {
34		if os.Getenv(helperMode) == "1" {
35			os.Exit(runAsHelper())
36		}
37		// Scan logs the command of every stage it starts, which is useful in the
38		// application and pure noise across a suite that runs hundreds of them.
39		log.SetOutput(io.Discard)
40		os.Exit(m.Run())
41	}
42	
43	func runAsHelper() int {
44		if refused := os.Getenv(helperFailOn); refused != "" && slices.Contains(os.Args[1:], refused) {
45			_, _ = fmt.Fprintln(os.Stderr, "cannot connect to the daemon")
46			return 1
47		}
48		if out := os.Getenv(helperStdout); out != "" {
49			_, _ = fmt.Fprint(os.Stdout, out)
50		}
51		if diag := os.Getenv(helperStderr); diag != "" {
52			for line := range strings.SplitSeq(diag, "\n") {
53				_, _ = fmt.Fprintln(os.Stderr, line)
54			}
55		}
56		code, _ := strconv.Atoi(os.Getenv(helperExit))
57		return code
58	}
