60	// asScanner points a toolCmd at the test binary and tells it what to produce.
61	func asScanner(t *testing.T, stdout, stderr string, exit int) toolCmd {
62		t.Helper()
63		self, err := os.Executable()
64		if err != nil {
65			t.Fatalf("locating the test binary: %v", err)
66		}
67		t.Setenv(helperMode, "1")
68		t.Setenv(helperStdout, stdout)
69		t.Setenv(helperStderr, stderr)
70		t.Setenv(helperExit, strconv.Itoa(exit))
71		t.Setenv(helperFailOn, "")
72		return toolCmd{Name: self}
73	}
