11	// Detection probes the machine it runs on, which is exactly what a test must
12	// not do. Instead the tools are installed on a PATH of the test's own making:
13	// each one is a copy of the test binary, which already knows how to behave as a
14	// scanner (see run_test.go).
15	
16	// installTools puts the named tools on an otherwise empty PATH and makes them
17	// answer with output. An empty output is a tool that prints nothing, which is
18	// how "docker has no such image" is expressed.
19	func installTools(t *testing.T, output string, names ...string) {
20		t.Helper()
21	
22		self, err := os.Executable()
23		if err != nil {
24			t.Fatalf("locating the test binary: %v", err)
25		}
26		body, err := os.ReadFile(self)
27		if err != nil {
28			t.Fatalf("reading the test binary: %v", err)
29		}
30	
31		dir := t.TempDir()
32		for _, name := range names {
33			if runtime.GOOS == "windows" {
34				name += ".exe"
35			}
36			if err := os.WriteFile(filepath.Join(dir, name), body, 0o755); err != nil {
37				t.Fatalf("installing %s: %v", name, err)
38			}
39		}
40	
41		t.Setenv("PATH", dir)
42		t.Setenv(helperMode, "1")
43		t.Setenv(helperStdout, output)
44		t.Setenv(helperStderr, "")
45		t.Setenv(helperExit, "0")
46	}
