13		} else if b.tagSortCol == tagSortByName && b.tagSortDesc {
14			b.tagSortCol = tagSortByUpdated
15			b.tagSortDesc = false
16		} else if b.tagSortCol == tagSortByUpdated && !b.tagSortDesc {
17			b.tagSortDesc = true
18		} else {
19			b.tagSortCol = tagSortByName
20			b.tagSortDesc = false
21		}
22		b.rebuildTagTable()
23	}
24	
25	func (b *RegistryBrowser) cycleRegistryFilter() {
26		seen := make(map[string]bool)
27		var urls []string
28		for _, t := range b.tags {
29			if !seen[t.RegistryURL] {
30				seen[t.RegistryURL] = true
31				urls = append(urls, t.RegistryURL)
32			}
33		}
34		if len(urls) <= 1 {
35			b.registryFilter = ""
36			b.rebuildTagTable()
37			return
38		}
39		if b.registryFilter == "" {
40			b.registryFilter = urls[0]
41		} else {
42			found := false
43			for i, u := range urls {
44				if u == b.registryFilter {
45					next := (i + 1) % (len(urls) + 1)
46					if next == len(urls) {
47						b.registryFilter = ""
48					} else {
49						b.registryFilter = urls[next]
50					}
51					found = true
52					break
53				}
54			}
55			if !found {
56				b.registryFilter = ""
57			}
58		}
59		b.rebuildTagTable()
60	}
