110	// normalizeRepoForRegistry prepends "library/" for bare names on Docker Hub.
111	func normalizeRepoForRegistry(registryURL, repo string) string {
112		if strings.Contains(repo, "/") {
113			return repo
114		}
115		base := strings.ToLower(strings.TrimSuffix(registryURL, "/"))
116		for _, alias := range []string{"docker.io", "registry-1.docker.io"} {
117			if base == alias {
118				return "library/" + repo
119			}
120		}
121		return repo
122	}
123	
124	// multiImageName constructs the full image reference for pull/scan.
125	func multiImageName(registryURL, repo, tag string) string {
126		base := strings.TrimSuffix(registryURL, "/")
127		for _, alias := range []string{"docker.io", "registry-1.docker.io"} {
128			if strings.EqualFold(base, alias) {
129				return repo + ":" + tag
130			}
131		}
132		return base + "/" + repo + ":" + tag
133	}
