135	func (b *RegistryBrowser) updateFocus() {
136		b.repoInput.Blur()
137		if b.focusedField == brFieldRepo {
138			b.repoInput.Focus()
139		}
140	}
141	
142	// filteredSortedMultiTags returns tags after applying registry filter, text filter, and sort.
143	func (b *RegistryBrowser) filteredSortedMultiTags() []MultiRegistryTag {
144		query := strings.ToLower(b.filterInput.Value())
145		var result []MultiRegistryTag
146		for _, t := range b.tags {
147			if b.registryFilter != "" && t.RegistryURL != b.registryFilter {
148				continue
149			}
150			if query != "" && !strings.Contains(strings.ToLower(t.Tag), query) &&
151				!strings.Contains(strings.ToLower(t.Repo), query) {
152				continue
153			}
154			result = append(result, t)
155		}
156	
157		sortCol := b.tagSortCol
158		sortDesc := b.tagSortDesc
159		sort.SliceStable(result, func(i, j int) bool {
160			var less bool
161			switch sortCol {
162			case tagSortByUpdated:
163				less = result[i].UpdatedAt.After(result[j].UpdatedAt)
164			default:
165				less = strings.ToLower(result[i].Tag) < strings.ToLower(result[j].Tag)
166			}
167			if sortDesc {
168				return !less
169			}
170			return less
171		})
172		return result
173	}
