89	func (b *RegistryBrowser) viewInput() string {
90		var sb strings.Builder
91	
92		sb.WriteString(theme.EmptyLineBg(b.width) + "\n")
93		sb.WriteString(b.renderInputField("Repository", b.repoInput.View(), brFieldRepo))
94		sb.WriteString("\n\n")
95	
96		if len(b.entries) > 0 {
97			sb.WriteString(theme.Bg("  ") + theme.DimStyle.Render("Registries:") + "\n")
98			var currentGroup string
99			for i, entry := range b.entries {
100				if entry.ParentAlias != "" && entry.ParentAlias != currentGroup {
101					if currentGroup != "" {
102						sb.WriteString("\n")
103					}
104					currentGroup = entry.ParentAlias
105					sb.WriteString(theme.Bg("  ") + theme.DimStyle.Render(currentGroup+":") + "\n")
106				} else if entry.ParentAlias == "" && currentGroup != "" {
107					currentGroup = ""
108					sb.WriteString("\n")
109				}
110				label := entry.Alias
111				if entry.ParentAlias != "" {
112					label = "  " + entry.Alias // visual indent for group members
113				}
114				checked := b.selectedRegs[entry.URL]
115				focused := b.focusedField == b.brFieldReg(i)
116				sb.WriteString(theme.RenderCheckbox(checked, label, focused))
117				if i < len(b.entries)-1 {
118					sb.WriteString("\n")
119				}
120			}
121			sb.WriteString("\n\n")
122		}
123	
124		sb.WriteString("  ")
