130	func (b *RegistryBrowser) renderInputField(label, value string, fieldIdx int) string {
131		var labelStr string
132		if b.focusedField == fieldIdx {
133			labelStr = theme.KeyStyle.Render(theme.IconCircleSmall + " " + label + " " + theme.IconChevronRight)
134		} else {
135			labelStr = theme.Bg("  " + label + " " + theme.IconChevronRight)
136		}
137		return labelStr + "\n  " + value
138	}
139	
140	func (b *RegistryBrowser) viewTags() string {
141		displayed := b.filteredSortedMultiTags()
142		if len(displayed) == 0 {
143			if b.pendingSearches > 0 {
144				return theme.EmptyLineBg(b.width) + "\n" +
145					theme.SpinnerMessage(b.spinner.View(), "Searching registries...")
146			}
147			return theme.DimStyle.Render("  No tags found")
148		}
149		return b.tagTable.View()
150	}
151	
152	// FilterIsVisible returns true when the tag filter bar should be shown in the footer.
153	func (b *RegistryBrowser) FilterIsVisible() bool {
154		return b.state == browserStateTags && (b.filterActive || b.filterInput.Value() != "" || b.registryFilter != "")
155	}
156	
157	// FilterBarView renders the filter bar (2 lines) for display in the footer.
158	func (b *RegistryBrowser) FilterBarView(width int) string {
159		borderStyle := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)
160	
161		var left string
162		if b.filterActive {
163			left = theme.KeyStyle.Render("/") + theme.Bg(" ") + b.filterInput.View()
164		} else if b.filterInput.Value() != "" {
165			left = theme.DimStyle.Render("/ ") + theme.KeyStyle.Render(b.filterInput.Value())
166		} else {
167			left = theme.DimStyle.Render("/ filter…")
168		}
169	
170		if b.registryFilter != "" {
171			left += theme.Bg("  ") + theme.KeyStyle.Render("["+b.registryFilterLabel()+"]")
172		}
173	
174		inner := theme.Bg(" ") + left
175		paddedInner := theme.PadWithBg(inner, width-2)
176		contentLine := borderStyle.Render("│") + paddedInner + borderStyle.Render("│")
177		bottomBorder := borderStyle.Render("└" + strings.Repeat("─", width-2) + "┘")
178		return contentLine + "\n" + bottomBorder
179	}
180	
181	func (b *RegistryBrowser) viewStatus() string {
182		var label string
183		switch b.operation {
184		case "pull":
185			label = "Pulling " + b.imageName + "..."
186		default:
187			label = "Working..."
188		}
189		return theme.EmptyLineBg(b.width) + "\n" +
190			theme.SpinnerMessage(b.spinner.View(), label)
191	}
