11	// handleImageExposedPorts opens the launch form once exposed ports are fetched
12	func (m Model) handleImageExposedPorts(msg ImageExposedPortsMsg) (tea.Model, tea.Cmd) {
13		if msg.Err != nil {
14			log.Printf("ERROR [oci_resources] exposed ports %s: %v", msg.ImageName, msg.Err)
15		}
16		m.launchForm = NewLaunchForm(msg.ImageName, msg.Ports, m.networks, m.width-2)
17		return m, loadLaunchOptionsCmd(msg.ImageName)
18	}
