20	// handleLaunchOptionsCacheLoaded applies cached options to the launch form if it is still open.
21	func (m Model) handleLaunchOptionsCacheLoaded(msg LaunchOptionsCacheLoadedMsg) (tea.Model, tea.Cmd) {
22		if m.launchForm == nil || msg.Entry == nil || m.launchForm.image != msg.ImageName {
23			return m, nil
24		}
25		m.launchForm.ApplyCached(*msg.Entry)
26		// Trigger entrypoint verification if a cached entrypoint is present
27		if msg.Entry.Entrypoint != "" {
28			m.launchForm.verify = verifyChecking
29			m.launchForm.verifySeq++
30			return m, verifyEntrypointCmd(m.launchForm.verifySeq, m.launchForm.image, msg.Entry.Entrypoint)
31		}
32		return m, nil
33	}
34	
35	// handleContainerLaunchComplete processes container launch results
36	func (m Model) handleContainerLaunchComplete(msg ContainerLaunchCompleteMsg) (tea.Model, tea.Cmd) {
37		if msg.Err != nil {
38			log.Printf("ERROR [oci_resources] launch container: %v", msg.Err)
39			m.errorMsg = "Failed to launch container — check logs"
40			m.lastLaunchOpts = nil
41			m.lastLaunchImage = ""
42			return m, clearInfoMsgCmd()
43		}
44		m.errorMsg = ""
45		if m.lastLaunchOpts != nil {
46			saveCmd := saveLaunchOptionsCmd(m.lastLaunchImage, *m.lastLaunchOpts)
47			m.lastLaunchOpts = nil
48			m.lastLaunchImage = ""
49			return m, saveCmd
50		}
51		return m, nil
52	}
53	
54	// handleClipboardCopy processes the result of copying the docker command to clipboard (Rule 128).
55	// clearInfoMsgCmd clears both errorMsg and infoMsg after 3 seconds — correct for both branches.
56	func (m Model) handleClipboardCopy(msg ClipboardCopyMsg) (tea.Model, tea.Cmd) {
57		if msg.Err != nil {
58			log.Printf("ERROR [oci_resources] clipboard copy: %v", msg.Err)
59			m.errorMsg = "Failed to copy command to clipboard"
60		} else {
61			m.infoMsg = "Docker command copied to clipboard"
62		}
63		return m, clearInfoMsgCmd()
64	}
