66	// handleLaunchFormSubmit dispatches the container launch.
67	// handleLaunchFormSubmitWithCache snapshots form state into the pending save
68	// fields before delegating to handleLaunchFormSubmit.
69	func (m Model) handleLaunchFormSubmitWithCache(msg LaunchFormSubmitMsg) (tea.Model, tea.Cmd) {
70		if m.launchForm != nil {
71			entry := m.launchForm.ToCacheEntry()
72			m.lastLaunchOpts = &entry
73			m.lastLaunchImage = m.launchForm.image
