556	// Always emits RegistryGroupDetectedMsg (Members==nil means not a group).
557	func detectRegistryGroupCmd(reg config.RegistryItem, password string) tea.Cmd {
558		return func() tea.Msg {
559			ctx, cancel := context.WithTimeout(context.Background(), 8*time.Second)
560			defer cancel()
561	
562			username := reg.Username
563			// D12: a registry the user marked anonymous is probed anonymously.
564			// Docker keys credentials by host, so without this gate the credentials
565			// stored for any registry on that host went out to all of them — which,
566			// for a Nexus instance, is every repository it serves.
