package datatable

// Rule 116: the column widths must sum to exactly the space available, or the
// selected row stops short of the right viewport border.
//
// Every view enforced that the same way — last column absorbs the remainder —
// and several then applied a per-column `max(…, floor)` *after* the remainder
// was computed, which silently pushes the sum back over. `workspaces` overflows
// by 34 columns on a 120-wide terminal that way.
//
// The fix is not a better clamp. It is to distribute the shortfall across the
// columns instead of letting each one defend its own floor: a floor that cannot
// be honoured has to be given up by somebody, and deciding that here is what
// makes the invariant hold at every width rather than most of them.

// borderWidth is the viewport's two vertical borders.
const borderWidth = 2

// cellPadding is what bubbles/table adds per column — Padding(0, 1).
const cellPadding = 2

// availableFor returns the width the columns have to share, given the full
// viewport width. Negative when the terminal cannot even hold the borders and
// the padding, which the solver reads as "no room at all".
func availableFor(viewportWidth, numColumns int) int {
	return viewportWidth - borderWidth - numColumns*cellPadding
}

// solveWidths distributes available across the columns.
//
// Fixed columns (Flex == 0) ask for MinWidth. Flexible ones ask for MinWidth
// and share whatever is left in proportion to their Flex weight. When there is
// not enough for everyone, the shortfall comes out of the flexible columns
// first and the fixed ones only after — a fixed column is fixed because its
// content has a known size, so it is the last thing worth truncating.
//
// The result always sums to exactly max(available, 0).
func solveWidths[T any](columns []Column[T], available int) []int {
	widths := make([]int, len(columns))
	if len(columns) == 0 || available <= 0 {
		return widths
	}

	total := 0
	for i, c := range columns {
		widths[i] = max(c.MinWidth, 0)
		total += widths[i]
	}

	switch {
	case total < available:
		grow(columns, widths, available-total)
	case total > available:
		shrink(columns, widths, total-available)
	}
	return widths
}

// grow hands the surplus to the flexible columns by weight, giving the last one
// the rounding remainder so the sum is exact. With no flexible column the last
// column absorbs it, which is what every view did by hand.
func grow[T any](columns []Column[T], widths []int, surplus int) {
	weight := 0
	last := -1
	for i, c := range columns {
		if c.Flex > 0 {
			weight += c.Flex
			last = i
		}
	}
	if weight == 0 {
		widths[len(widths)-1] += surplus
		return
	}

	given := 0
	for i, c := range columns {
		if c.Flex <= 0 || i == last {
			continue
		}
		share := surplus * c.Flex / weight
		widths[i] += share
		given += share
	}
	widths[last] += surplus - given
}

// shrink reclaims the shortfall, taking from the flexible columns before the
// fixed ones and from the widest before the narrowest, so that one long column
// gives way before several short ones become unreadable.
func shrink[T any](columns []Column[T], widths []int, shortfall int) {
	shortfall = takeFrom(widths, order(columns, true), shortfall)
	takeFrom(widths, order(columns, false), shortfall)
}

// order returns the column indices to reclaim from, widest first, restricted to
// the flexible ones or the fixed ones.
func order[T any](columns []Column[T], flexible bool) []int {
	var idx []int
	for i, c := range columns {
		if (c.Flex > 0) == flexible {
			idx = append(idx, i)
		}
	}
	return idx
}

// takeFrom removes shortfall from the given columns one unit at a time, always
// from the widest, and returns what could not be taken. One unit at a time
// keeps it exact and level: no column is emptied while another stays wide.
func takeFrom(widths []int, idx []int, shortfall int) int {
	for shortfall > 0 {
		widest, at := 0, -1
		for _, i := range idx {
			if widths[i] > widest {
				widest, at = widths[i], i
			}
		}
		if at < 0 {
			return shortfall // nothing left with any width to give
		}
		widths[at]--
		shortfall--
	}
	return 0
}

// Package datatable is the shared mechanism behind the application's tables.
//
// What was shared before was only the *look* — theme.DefaultTableStyles,
// TableStylesForState/ForSeverity, components.FilterBar, theme.TimeAgo. Column
// widths, sorting, sort arrows, filter matching, cursor clamping and
// cursor-to-object resolution were written out again in each of the fifteen
// tables, and drifted:
//
//   - Rule 116's width invariant is broken by five of the twelve copies, which
//     clamp per column after the remainder has been computed (see widths.go).
//   - Two of eight clamp the cursor when the row count shrinks; the rest leave
//     it dangling, and oci_resources compensates by jumping to the top on every
//     filter toggle, throwing away the scroll position.
//   - Nine getSelectedX() replay filter-then-sort by hand to map a cursor back
//     to an object, with nothing tying that ordering to the one the rows were
//     built from. If they drift, the action lands on the wrong object and says
//     nothing. That is the duplication worth removing on correctness grounds.
//
// Here the filtered, sorted slice is built once and kept, so Selected() cannot
// disagree with what is on screen, and Cell func(T) string gives styled text
// nowhere to go — Rule 122 by construction rather than by review.
package datatable

import (
	"sort"
	"strings"

	"github.com/charmbracelet/bubbles/table"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// Column describes one column and how to get its value out of an item.
type Column[T any] struct {
	Title string
	// MinWidth is what the column asks for. It is a request, not a guarantee:
	// when the terminal is too narrow for every request, the shortfall is
	// shared out rather than each column defending its own floor.
	MinWidth int
	// Flex is the column's share of the space left over. 0 keeps it at
	// MinWidth; the leftover is split between the flexible ones by weight.
	Flex int
	// Cell returns the text for this column. Plain text only: bubbles/table
	// truncates with runewidth, which does not understand ANSI, so a styled
	// string is cut mid-escape and bleeds over every row below it (Rule 122).
	// Taking a string rather than a styled value is what makes that
	// unexpressible here.
	Cell func(T) string
	// Less sorts by this column. Nil means the column cannot be sorted by, and
	// `.` skips it.
	Less func(a, b T) bool
	// Search is what the text filter matches against. Nil means the column does
	// not participate.
	Search func(T) string
}

// Config is everything a view has to say about its table.
type Config[T any] struct {
	Columns []Column[T]
	// Tokens are the toggle filters shown in the bar (Rule 136).
	Tokens []components.FilterToken
	// TokenMatch decides whether an item passes the active toggles. Nil means
	// the toggles are ignored, which is only sensible with no Tokens.
	TokenMatch func(item T, active map[string]bool) bool
	// SortColumn is the column sorted by on open; -1 for no initial sort.
	SortColumn int
	// SelectedStyles returns the table styles to use while the given item is
	// under the cursor — that is the only thing bubbles/table can vary per
	// selection, and it is what containers and security each re-derived by
	// hand. Returning a style rather than a state keyword is what keeps this
	// package from having to know what a severity is. Nil means the default.
	SelectedStyles func(T) table.Styles
}

// Model is a table over a slice of T.
type Model[T any] struct {
	cfg   Config[T]
	table table.Model
	bar   components.FilterBar

	items []T
	// visible is the filtered, sorted slice the rows were built from. Selected()
	// reads it rather than recomputing, so the cursor cannot point at one
	// ordering while the screen shows another.
	visible []T

	sortColumn int
	sortDesc   bool
	width      int
}

// New builds a table from its configuration.
func New[T any](cfg Config[T]) Model[T] {
	cols := make([]table.Column, len(cfg.Columns))
	for i, c := range cfg.Columns {
		cols[i] = table.Column{Title: c.Title, Width: c.MinWidth}
	}
	t := table.New(table.WithColumns(cols), table.WithFocused(true), table.WithHeight(10))
	t.SetStyles(theme.DefaultTableStyles())

	bar := components.NewFilterBar()
	if len(cfg.Tokens) > 0 {
		bar = components.NewFilterBarWithTokens(cfg.Tokens)
	}

	m := Model[T]{cfg: cfg, table: t, bar: bar, sortColumn: cfg.SortColumn}
	if m.sortColumn >= len(cfg.Columns) {
		m.sortColumn = -1
	}
	return m
}

// SetItems replaces the contents. Filtering, sorting, row building and the
// cursor clamp all happen here and only here, which is what stops a cursor from
// being left pointing past the end — bubbles/table's SetRows does not clamp, and
// the stale cursor is invisible until the user presses a key.
func (m *Model[T]) SetItems(items []T) {
	m.items = items
	m.rebuild()
}

// Items returns everything held, filtered or not.
func (m *Model[T]) Items() []T { return m.items }

// Visible returns what is on screen, in the order it is on screen.
func (m *Model[T]) Visible() []T { return m.visible }

// Selected returns the item under the cursor. The bool is false when there is
// nothing to select, which is the only case a caller has to handle.
func (m *Model[T]) Selected() (T, bool) {
	cursor := m.table.Cursor()
	if cursor < 0 || cursor >= len(m.visible) {
		var zero T
		return zero, false
	}
	return m.visible[cursor], true
}

// Cursor returns the selected row index.
func (m *Model[T]) Cursor() int { return m.table.Cursor() }

// GotoTop moves the cursor to the first row. Views that want the cursor reset
// on a change of scope — security resets it when the tab changes — call this
// explicitly, because SetItems deliberately does not.
func (m *Model[T]) GotoTop() { m.table.GotoTop() }

// FilterBar exposes the bar for RenderFooter and GetFooterHeight (Rule 136).
func (m *Model[T]) FilterBar() *components.FilterBar { return &m.bar }

// InEditMode reports whether the search field has the keyboard.
func (m *Model[T]) InEditMode() bool { return m.bar.InEditMode() }

// Table exposes the underlying table for rendering.
func (m *Model[T]) Table() *table.Model { return &m.table }

// View renders the table.
func (m *Model[T]) View() string { return m.table.View() }

// SetHeight sets the number of rows shown.
func (m *Model[T]) SetHeight(h int) { m.table.SetHeight(max(h, 1)) }

// Focus and Blur move the keyboard between two tables sharing a viewport, which
// is what the status view does with its monitors and its certificates.
func (m *Model[T]) Focus() {
	m.table.Focus()
	m.applyStyles()
}

func (m *Model[T]) Blur() {
	m.table.Blur()
	m.table.SetStyles(theme.BlurredTableStyles())
}

// Resize recomputes the column widths for a viewport of this width (Rule 116).
// The width passed is the full viewport width, borders included; the borders and
// the per-cell padding are subtracted here so no caller has to remember to.
func (m *Model[T]) Resize(width, height int) {
	m.width = width
	widths := solveWidths(m.cfg.Columns, availableFor(width, len(m.cfg.Columns)))

	cols := m.table.Columns()
	for i := range cols {
		cols[i].Width = widths[i]
		cols[i].Title = m.titleFor(i)
	}
	m.table.SetColumns(cols)
	m.bar.Resize(width)
	if height > 0 {
		m.SetHeight(height)
	}
}

// titleFor returns a column's header, with a sort arrow on the active one.
func (m *Model[T]) titleFor(i int) string {
	if i != m.sortColumn {
		return m.cfg.Columns[i].Title
	}
	if m.sortDesc {
		return m.cfg.Columns[i].Title + " ▼"
	}
	return m.cfg.Columns[i].Title + " ▲"
}

// CycleSort advances the sort: ascending, descending, then on to the next
// sortable column (Rule 111's `.`). Returns to no sort after the last one when
// the table opened unsorted, so the original order stays reachable.
func (m *Model[T]) CycleSort() {
	sortable := m.sortableColumns()
	if len(sortable) == 0 {
		return
	}
	switch {
	case m.sortColumn < 0:
		m.sortColumn, m.sortDesc = sortable[0], false
	case !m.sortDesc:
		m.sortDesc = true
	default:
		m.sortColumn, m.sortDesc = m.nextSortable(sortable), false
	}
	m.rebuild()
	m.Resize(m.width, 0) // the arrow moved
}

// nextSortable returns the column after the current one, wrapping to the first —
// or to -1 when the table opened unsorted, so "no sort" is a stop on the cycle.
func (m *Model[T]) nextSortable(sortable []int) int {
	for i, col := range sortable {
		if col != m.sortColumn {
			continue
		}
		if i+1 < len(sortable) {
			return sortable[i+1]
		}
		if m.cfg.SortColumn < 0 {
			return -1
		}
		return sortable[0]
	}
	return sortable[0]
}

func (m *Model[T]) sortableColumns() []int {
	var out []int
	for i, c := range m.cfg.Columns {
		if c.Less != nil {
			out = append(out, i)
		}
	}
	return out
}

// SortState reports the column sorted by and its direction, for tests and for
// views that show it elsewhere. Column is -1 when nothing is sorted.
func (m *Model[T]) SortState() (column int, desc bool) { return m.sortColumn, m.sortDesc }

// Update handles the keys every table shares: navigation, `/` for the search,
// `.` for the sort, and whatever the filter bar takes while it is focused.
// Anything else is left alone, so the view keeps its own actions.
func (m *Model[T]) Update(msg tea.Msg) tea.Cmd {
	if m.bar.InEditMode() {
		var cmd tea.Cmd
		m.bar, cmd = m.bar.Update(msg)
		m.rebuild()
		return cmd
	}

	key, ok := msg.(tea.KeyMsg)
	if !ok {
		return nil
	}
	switch key.String() {
	case "/":
		return m.bar.ActivateSearch()
	case ".":
		m.CycleSort()
	case "up", "k":
		m.table.MoveUp(1)
		m.applyStyles()
	case "down", "j":
		m.table.MoveDown(1)
		m.applyStyles()
	case "pgup":
		m.table.MoveUp(m.table.Height())
		m.applyStyles()
	case "pgdown":
		m.table.MoveDown(m.table.Height())
		m.applyStyles()
	case "g", "home":
		m.table.GotoTop()
		m.applyStyles()
	case "G", "end":
		m.table.GotoBottom()
		m.applyStyles()
	}
	return nil
}

// SetTokenActive toggles one of the bar's filter tokens and re-applies it.
func (m *Model[T]) SetTokenActive(label string, active bool) {
	m.bar.SetTokenActive(label, active)
	m.rebuild()
}

// IsTokenActive reports whether a toggle filter is on.
func (m *Model[T]) IsTokenActive(label string) bool { return m.bar.IsTokenActive(label) }

// rebuild filters, sorts, writes the rows and puts the cursor somewhere real.
func (m *Model[T]) rebuild() {
	m.visible = m.sorted(m.filtered())

	rows := make([]table.Row, len(m.visible))
	for i, item := range m.visible {
		cells := make(table.Row, len(m.cfg.Columns))
		for j, c := range m.cfg.Columns {
			cells[j] = c.Cell(item)
		}
		rows[i] = cells
	}
	m.table.SetRows(rows)

	// bubbles/table leaves the cursor where it was, so a list that just got
	// shorter strands it past the end until the user presses a key.
	if cursor := m.table.Cursor(); cursor >= len(rows) {
		m.table.SetCursor(max(len(rows)-1, 0))
	}
	m.applyStyles()
}

// applyStyles asks the view for the styles that go with the selected item.
func (m *Model[T]) applyStyles() {
	if !m.table.Focused() {
		return // Blur owns the styles until Focus takes them back
	}
	styles := theme.DefaultTableStyles()
	if item, ok := m.Selected(); ok && m.cfg.SelectedStyles != nil {
		styles = m.cfg.SelectedStyles(item)
	}
	m.table.SetStyles(styles)
}

// filtered applies the search query and the toggle filters.
func (m *Model[T]) filtered() []T {
	query := strings.ToLower(strings.TrimSpace(m.bar.SearchQuery()))
	active := m.activeTokens()

	out := make([]T, 0, len(m.items))
	for _, item := range m.items {
		if m.cfg.TokenMatch != nil && !m.cfg.TokenMatch(item, active) {
			continue
		}
		if query != "" && !m.matchesQuery(item, query) {
			continue
		}
		out = append(out, item)
	}
	return out
}

func (m *Model[T]) activeTokens() map[string]bool {
	active := make(map[string]bool, len(m.cfg.Tokens))
	for _, tok := range m.cfg.Tokens {
		if m.bar.IsTokenActive(tok.Label) {
			active[tok.Label] = true
		}
	}
	return active
}

func (m *Model[T]) matchesQuery(item T, query string) bool {
	for _, c := range m.cfg.Columns {
		if c.Search == nil {
			continue
		}
		if strings.Contains(strings.ToLower(c.Search(item)), query) {
			return true
		}
	}
	return false
}

// sorted orders the visible slice. SliceStable, because sort.Slice is not and
// two rows equal on the sort column would otherwise swap between rebuilds.
func (m *Model[T]) sorted(items []T) []T {
	if m.sortColumn < 0 || m.sortColumn >= len(m.cfg.Columns) {
		return items
	}
	less := m.cfg.Columns[m.sortColumn].Less
	if less == nil {
		return items
	}
	desc := m.sortDesc
	sort.SliceStable(items, func(i, j int) bool {
		if desc {
			return less(items[j], items[i])
		}
		return less(items[i], items[j])
	})
	return items
}

package datatable

import (
	"testing"
)

// The invariant this package exists to hold: the widths sum to exactly what is
// available, at every terminal width, so the selected row reaches the right
// viewport border (Rule 116). Testing it once here is what replaces checking
// twelve hand-written copies in review.

// col is a column with only the fields the solver reads.
func col(minWidth, flex int) Column[string] {
	return Column[string]{MinWidth: minWidth, Flex: flex}
}

func sum(widths []int) int {
	total := 0
	for _, w := range widths {
		total += w
	}
	return total
}

func TestTheWidthsAlwaysSumToWhatIsAvailable(t *testing.T) {
	layouts := map[string][]Column[string]{
		"one flexible column":     {col(20, 1)},
		"fixed and flexible":      {col(16, 0), col(20, 1), col(10, 0)},
		"two flexible columns":    {col(10, 1), col(10, 3)},
		"all fixed":               {col(12, 0), col(8, 0), col(30, 0)},
		"the workspaces shape":    workspacesShape(),
		"a column asking for one": {col(1, 0), col(60, 1)},
	}

	// Every width from unusable to generous, including the ones the hand-written
	// clamps get wrong.
	for name, columns := range layouts {
		for width := 0; width <= 200; width++ {
			widths := solveWidths(columns, availableFor(width, len(columns)))
			want := max(availableFor(width, len(columns)), 0)

			if got := sum(widths); got != want {
				t.Fatalf("%s at width %d: the widths sum to %d, want %d (%v)", name, width, got, want, widths)
			}
			for i, w := range widths {
				if w < 0 {
					t.Fatalf("%s at width %d: column %d is %d wide", name, width, i, w)
				}
			}
		}
	}
}

// workspacesShape reproduces the layout that overflows today: eleven columns,
// 105 of fixed width, and two of them clamping after the remainder is computed.
// Below a 154-column terminal the hand-written version sums to 130 against a
// smaller available — 96 at width 120, an overflow of 34.
func workspacesShape() []Column[string] {
	return []Column[string]{
		col(24, 3), col(10, 0), col(15, 0), col(8, 0), col(8, 0),
		col(8, 0), col(8, 0), col(8, 0), col(8, 0), col(8, 0), col(8, 0),
	}
}

func TestTheWorkspacesShapeNoLongerOverflows(t *testing.T) {
	columns := workspacesShape()
	const width = 120

	widths := solveWidths(columns, availableFor(width, len(columns)))

	available := availableFor(width, len(columns))
	if got := sum(widths); got != available {
		t.Errorf("the widths sum to %d against an available of %d — the overflow is back", got, available)
	}
}

// A terminal too narrow for the borders and the padding alone has no room to
// give, and the answer has to be zeros rather than negative widths.
func TestNoRoomAtAllGivesZeroWidths(t *testing.T) {
	widths := solveWidths([]Column[string]{col(10, 1), col(10, 0)}, -4)

	if sum(widths) != 0 {
		t.Errorf("widths = %v, want all zero", widths)
	}
}

func TestNoColumnsIsNotACrash(t *testing.T) {
	if got := solveWidths(nil, 80); len(got) != 0 {
		t.Errorf("solveWidths(nil) = %v", got)
	}
}

// The leftover goes to the flexible columns in proportion to their weight.
func TestTheSurplusIsSharedByWeight(t *testing.T) {
	columns := []Column[string]{col(10, 1), col(10, 3), col(10, 0)}

	widths := solveWidths(columns, 70) // 30 asked for, 40 to share

	if widths[2] != 10 {
		t.Errorf("the fixed column is %d wide, want its %d", widths[2], 10)
	}
	if widths[0] != 20 || widths[1] != 40 {
		t.Errorf("widths = %v, want the leftover split 1:3 on top of the minimums", widths)
	}
}

// With nothing flexible the last column absorbs the remainder, which is what
// every view did by hand and what keeps the selected row reaching the border.
func TestWithNothingFlexibleTheLastColumnAbsorbs(t *testing.T) {
	widths := solveWidths([]Column[string]{col(10, 0), col(10, 0)}, 35)

	if widths[0] != 10 || widths[1] != 25 {
		t.Errorf("widths = %v, want the remainder on the last column", widths)
	}
}

// A fixed column is fixed because its content has a known size, so it is the
// last thing worth truncating: the shortfall comes out of the flexible ones
// first, and only then out of the fixed.
func TestTheShortfallComesOutOfTheFlexibleColumnsFirst(t *testing.T) {
	columns := []Column[string]{col(30, 1), col(10, 0)}

	widths := solveWidths(columns, 25) // 15 short

	if widths[1] != 10 {
		t.Errorf("the fixed column lost %d while a flexible one still had width", 10-widths[1])
	}
	if widths[0] != 15 {
		t.Errorf("widths = %v, want the flexible column to have given up the shortfall", widths)
	}
}

// Once the flexible columns are exhausted the fixed ones have to give way too,
// or the sum cannot hold.
func TestTheFixedColumnsGiveWayWhenNothingElseIsLeft(t *testing.T) {
	columns := []Column[string]{col(4, 1), col(20, 0), col(20, 0)}

	widths := solveWidths(columns, 10)

	if got := sum(widths); got != 10 {
		t.Fatalf("the widths sum to %d, want 10", got)
	}
	if widths[0] != 0 {
		t.Errorf("widths = %v, want the flexible column emptied before the fixed ones", widths)
	}
}

// Reclaiming from the widest first is what stops one column being emptied while
// another stays long.
func TestShrinkingLevelsTheColumnsRatherThanEmptyingOne(t *testing.T) {
	columns := []Column[string]{col(40, 1), col(10, 1)}

	widths := solveWidths(columns, 20) // 30 short

	if widths[1] == 0 {
		t.Errorf("widths = %v, want the long column to give way before the short one is emptied", widths)
	}
	if widths[0] < widths[1] {
		t.Errorf("widths = %v, want the wider column to still be the wider one", widths)
	}
}

// A negative MinWidth is a typo, not an instruction to take width away from the
// other columns.
func TestANegativeMinimumIsReadAsZero(t *testing.T) {
	widths := solveWidths([]Column[string]{col(-5, 0), col(10, 1)}, 30)

	if widths[0] != 0 {
		t.Errorf("widths = %v, want the negative minimum read as none", widths)
	}
	if sum(widths) != 30 {
		t.Errorf("the widths sum to %d, want 30", sum(widths))
	}
}

package datatable

import (
	"strings"
	"testing"

	"github.com/charmbracelet/bubbles/table"

	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/testutil"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// A domain type with something to sort by, something to search and something to
// colour the selection with — the three things the views actually do.
type row struct {
	Name  string
	Size  int
	State string
}

func testConfig() Config[row] {
	return Config[row]{
		SortColumn: 0,
		Columns: []Column[row]{
			{
				Title: "Name", MinWidth: 20, Flex: 1,
				Cell:   func(r row) string { return r.Name },
				Less:   func(a, b row) bool { return a.Name < b.Name },
				Search: func(r row) string { return r.Name },
			},
			{
				Title: "Size", MinWidth: 10,
				Cell: func(r row) string { return strings.Repeat("#", r.Size) },
				Less: func(a, b row) bool { return a.Size < b.Size },
			},
			{
				Title: "State", MinWidth: 12,
				Cell:   func(r row) string { return r.State },
				Search: func(r row) string { return r.State },
			},
		},
	}
}

func fixtures() []row {
	return []row{
		{Name: "api", Size: 3, State: "running"},
		{Name: "cache", Size: 1, State: "exited"},
		{Name: "web", Size: 2, State: "running"},
	}
}

func loaded(t *testing.T) Model[row] {
	t.Helper()
	m := New(testConfig())
	m.Resize(120, 10)
	m.SetItems(fixtures())
	return m
}

func names(items []row) []string {
	out := make([]string, len(items))
	for i, r := range items {
		out[i] = r.Name
	}
	return out
}

func equal(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// ── The cursor and the rows are one thing ────────────────────────────────────

// The duplication worth removing on correctness grounds: nine getSelectedX()
// replayed filter-then-sort by hand, with nothing tying that ordering to the one
// the rows were built from. Here there is one slice, so the cursor cannot point
// at a different object than the screen shows.
func TestSelectedAgreesWithTheRowOnScreen(t *testing.T) {
	m := loaded(t)

	for cursor := range m.Visible() {
		m.Table().SetCursor(cursor)
		item, ok := m.Selected()
		if !ok {
			t.Fatalf("nothing selected at cursor %d", cursor)
		}
		if got := m.Table().Rows()[cursor][0]; got != item.Name {
			t.Errorf("row %d shows %q while Selected() returns %q", cursor, got, item.Name)
		}
	}
}

// And it still agrees once a filter and a sort have reordered everything, which
// is where a hand-replayed pipeline drifts.
func TestSelectedStillAgreesAfterFilteringAndSorting(t *testing.T) {
	m := loaded(t)
	m.CycleSort() // Name descending

	m.Update(testutil.Key("/"))
	for _, msg := range testutil.Type("e") {
		m.Update(msg)
	}

	if len(m.Visible()) == 0 {
		t.Fatal("the filter matched nothing, so there is nothing to check")
	}
	for cursor := range m.Visible() {
		m.Table().SetCursor(cursor)
		item, _ := m.Selected()
		if got := m.Table().Rows()[cursor][0]; got != item.Name {
			t.Errorf("row %d shows %q while Selected() returns %q", cursor, got, item.Name)
		}
	}
}

func TestSelectedOnAnEmptyTableReportsNothing(t *testing.T) {
	m := New(testConfig())
	m.Resize(120, 10)

	if _, ok := m.Selected(); ok {
		t.Error("an empty table reported a selection")
	}
}

// bubbles/table.SetRows leaves the cursor where it was, so a list that just got
// shorter strands it past the end — invisible until the user presses a key, and
// clamped in only two of the eight tables that needed it.
func TestTheCursorIsClampedWhenTheListShrinks(t *testing.T) {
	m := loaded(t)
	m.Table().SetCursor(2)

	m.SetItems(fixtures()[:1])

	if got := m.Cursor(); got != 0 {
		t.Errorf("cursor = %d after the list shrank to one row, want 0", got)
	}
	if item, ok := m.Selected(); !ok || item.Name != "api" {
		t.Errorf("Selected() = %+v, %v — want the row that is actually there", item, ok)
	}
}

// The other half: a refresh that does not shorten the list must leave the
// cursor alone. netdiag's ports table rebuilds every two seconds, and jumping
// to the top each time is what its lazy-rebuild workaround exists to avoid.
func TestARefreshKeepsTheCursorWhereItWas(t *testing.T) {
	m := loaded(t)
	m.Table().SetCursor(2)

	m.SetItems(fixtures()) // same length, new slice

	if got := m.Cursor(); got != 2 {
		t.Errorf("cursor = %d after a refresh, want it left at 2", got)
	}
}

// A view that does want the cursor reset — security resets it on a tab change —
// has to say so, because that is the exception.
func TestGotoTopIsExplicit(t *testing.T) {
	m := loaded(t)
	m.Table().SetCursor(2)

	m.GotoTop()

	if got := m.Cursor(); got != 0 {
		t.Errorf("cursor = %d after GotoTop, want 0", got)
	}
}

// ── Sorting ──────────────────────────────────────────────────────────────────

func TestTheTableOpensSortedOnItsDefaultColumn(t *testing.T) {
	m := loaded(t)

