	cfg := testConfig()
	cfg.SelectedStyles = func(row) table.Styles {
		asked++
		return theme.DefaultTableStyles()
	}
	m := New(cfg)
	m.Resize(120, 10)
	m.Blur()
	before := asked

	m.SetItems(fixtures())

