func (pm *PortsModel) handleKeySearch(msg tea.KeyMsg) (*PortsModel, tea.Cmd) {
	var cmd tea.Cmd
	pm.filterBar, cmd = pm.filterBar.Update(msg)
	pm.applyFilters()
	pm.rebuildTable()
	pm.table.GotoTop()
