17	// filteredImages returns images matching the current filter
18	func (m *Model) filteredImages() []docker.Image {
19		query := strings.ToLower(m.filterBar.SearchQuery())
20		if query == "" {
21			return m.images
22		}
23		var result []docker.Image
24		for _, img := range m.images {
25			if strings.Contains(strings.ToLower(img.Repository), query) ||
26				strings.Contains(strings.ToLower(img.Tag), query) {
27				result = append(result, img)
28			}
29		}
30		return result
31	}
