33	// sortedImages returns images sorted by the current sort column
34	func (m *Model) sortedImages(images []docker.Image) []docker.Image {
35		sorted := make([]docker.Image, len(images))
36		copy(sorted, images)
37		sort.Slice(sorted, func(i, j int) bool {
38			a, b := sorted[i], sorted[j]
39			nameA := a.Name()
40			nameB := b.Name()
41			cacheA := m.scanCache[nameA]
42			cacheB := m.scanCache[nameB]
43			var less bool
44			switch m.sortColumn {
45			case sortByDiskUsage:
46				less = a.UniqueSize < b.UniqueSize
47			case sortByContentSize:
48				less = a.Size < b.Size
49			case sortByCritical:
50				less = cacheA.Critical < cacheB.Critical
51			case sortByHigh:
52				less = cacheA.High < cacheB.High
53			case sortByMedium:
54				less = cacheA.Medium < cacheB.Medium
55			case sortByLow:
56				less = cacheA.Low < cacheB.Low
57			case sortByScanned:
58				less = cacheA.ScannedAt.Before(cacheB.ScannedAt)
59			default:
60				less = strings.ToLower(nameA) < strings.ToLower(nameB)
61			}
62			if m.sortAsc {
63				return less
64			}
65			return !less
66		})
67		return sorted
68	}
