70	// formatBytes formats bytes into human-readable string
71	func formatBytes(b int64) string {
72		switch {
73		case b >= 1e9:
74			return fmt.Sprintf("%.1f GB", float64(b)/1e9)
75		case b >= 1e6:
76			return fmt.Sprintf("%.1f MB", float64(b)/1e6)
77		case b >= 1e3:
78			return fmt.Sprintf("%.1f kB", float64(b)/1e3)
79		default:
80			return fmt.Sprintf("%d B", b)
81		}
82	}
