217	// drilledGroup returns the group the tab has entered, or nil at the top level.
218	func (m *Model) drilledGroup() *config.RegistryItem {
219		if m.registryGroupSlug == "" {
220			return nil
221		}
222		for i := range m.registries {
223			if m.registries[i].Slug == m.registryGroupSlug {
224				return &m.registries[i]
225			}
226		}
227		return nil
228	}
