230	func (m *Model) updateRegistryTable() {
231		if group := m.drilledGroup(); group != nil {
232			m.updateGroupMemberTable(*group)
233			return
234		}
235		rows := make([]table.Row, 0, len(m.registries))
236		for _, reg := range m.registries {
237			rows = append(rows, table.Row{
238				reg.Alias, reg.URL, reg.Kind, reg.AuthMode,
239				m.loggedCell(reg.AuthMode, reg.URL), m.membersCell(reg),
240			})
241		}
242		m.setRegistryRows(rows)
243	}
