245	// updateGroupMemberTable fills the table with one group's discovered members.
246	//
247	// A member is not a config entry: it has no alias of its own to edit, its
248	// credentials are the group's, and it is what the cache holds — so the columns
249	// say `inherit` and carry no member count.
250	func (m *Model) updateGroupMemberTable(group config.RegistryItem) {
251		entry := m.groupCache[group.Slug]
252		rows := make([]table.Row, 0, len(entry.Members))
253		for _, member := range entry.Members {
254			rows = append(rows, table.Row{
255				member.Alias, member.URL, "member", config.AuthInherit,
256				m.loggedCell(group.AuthMode, group.URL), "",
257			})
258		}
259		m.setRegistryRows(rows)
260	}
