129	// cycleSort cycles through sort options
130	func (m Model) cycleSort() (tea.Model, tea.Cmd) {
131		if m.sortAsc {
132			m.sortAsc = false
133		} else {
134			m.sortAsc = true
135			nextIdx := 0
136			for i, col := range sortableColumns {
137				if col == m.sortColumn {
138					nextIdx = (i + 1) % len(sortableColumns)
139					break
140				}
141			}
142			m.sortColumn = sortableColumns[nextIdx]
143		}
144		m.updateImageTable()
145		return m, nil
146	}
