148	// requestScanAll launches a batch scan for all images with the configured options.
149	// Rule 126: purges the in-memory and disk cache before scanning.
150	func (m Model) requestScanAll() (tea.Model, tea.Cmd) {
151		if m.scanning {
152			return m, nil
153		}
154		var jobs []imageScanJob
155		var cacheKeys []string
156		for _, img := range m.images {
157			if img.Repository == "<none>" {
158				continue
159			}
160			name := img.Name()
161			jobs = append(jobs, imageScanJob{Name: name, Target: img.ScanTarget()})
162			cacheKeys = append(cacheKeys, name)
163			delete(m.scanCache, name)
164		}
165		if len(jobs) == 0 {
166			return m, nil
167		}
168		m.scanning = true
169		return m, tea.Batch(deleteScanCacheCmd(cacheKeys), batchScanCmd(jobs, m.defaultScanOpts()))
170	}
