219	// handleImageScanFinished updates scan results for a completed image scan.
220	func (m Model) handleImageScanFinished(msg ImageScanFinishedMsg) (tea.Model, tea.Cmd) {
221		delete(m.scanningImages, msg.ImageName)
222		if msg.Err != nil {
223			m.failedScans[msg.ImageName] = true
224		} else {
225			delete(m.failedScans, msg.ImageName)
226			m.scanCache[msg.ImageName] = msg.Entry
227			m.errorMsg = ""
228		}
229		m.scanning = len(m.scanningImages) > 0
230		m.updateImageTable()
231		if m.registryBrowser != nil {
232			m.registryBrowser.SetTagScanning(msg.ImageName, false)
233			m.registryBrowser.SetScanCache(m.scanCache)
234		}
235		return m, nil
236	}
