func TestTableCellsCarryNoANSISequences(t *testing.T) {
	withTrueColor(t)
	m := loadedModel(t)

	for _, row := range m.containerTable.Rows() {
		for i, cell := range row {
			if strings.Contains(cell, "\x1b") {
				t.Errorf("cell %d = %q contains an escape sequence", i, cell)
			}
		}
	}
}

