	}
	idx := m.table.Cursor()
	if idx < 0 || idx >= len(m.entries) {
		return m, nil
	}
	m.selectedIdx = idx
	m.mode = ModeRenaming
	m.input = NewRenameInput(m.entries[idx].Name)
