// applyTheme charge et applique un thème par nom
func (a *App) applyTheme(name string) tea.Cmd {
	cfgRef := a.config
	return func() tea.Msg {
		log.Printf("Applying theme: %s", name)
		t, err := theme.LoadTheme(name)
