}

func TestADisabledOptionCannotBeToggledAndSaysWhy(t *testing.T) {
	m := newModel(t)
	m.config.Scan.TrivyServer = "https://trivy:4954"
	m = focusOn(t, m, "Misconfiguration")

	m = feed(t, m, testutil.Key(" "))

