// renderField draws one setting (Rules 120, 132).
//
// Values are aligned on one column: twenty-nine settings whose values each start
// wherever their label happened to end reads as noise, and a cycle field's
// select icon makes its prefix two cells wider than a text field's, so the
// padding has to be measured on the whole prefix rather than on the label.
func (m Model) renderField(f field, focused bool) string {
	// A checkbox brings its own focus indicator and needs no value column.
	if f.Kind == kindToggle {
		if m.isDisabled(f) {
			return theme.Bg("  ") + theme.RenderCheckboxDisabled(f.Label)
		}
		return theme.RenderCheckbox(f.Bool(m.config), f.Label, focused)
	}

	indicator := "  "
	if focused {
		indicator = theme.IconCircleSmall + " "
	}
	prefix := indicator + m.pad(fieldPrefix(f))

	if focused {
		if f.Kind == kindCycle {
			return theme.KeyStyle.Render(prefix) + theme.Bg(f.Value(m.config))
		}
		return theme.KeyStyle.Render(prefix) + m.input.View()
	}
	return theme.Bg(prefix) + theme.Bg(f.Value(m.config))
}

// fieldPrefix is everything before the value (Rule 132's ordering).
func fieldPrefix(f field) string {
	if f.Kind == kindCycle {
		return f.Label + " " + theme.IconSelect + " " + theme.IconChevronRight + " "
	}
	return f.Label + " " + theme.IconChevronRight + " "
}

// pad widens a prefix to the active tab's value column.
func (m Model) pad(prefix string) string {
	if w := m.valueColumn() - lipgloss.Width(prefix); w > 0 {
		return prefix + strings.Repeat(" ", w)
	}
	return prefix
}

// valueColumn is where values start in the active tab: the widest prefix among
// the fields that have one. Checkboxes are excluded — they carry no value, so
// letting a long checkbox label push every value right would be padding for
// nothing.
func (m Model) valueColumn() int {
	widest := 0
	for _, f := range m.fields() {
		if f.Kind == kindToggle {
			continue
		}
		widest = max(widest, lipgloss.Width(fieldPrefix(f)))
	}
	return widest
}

